<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {api} from './api'
const props=defineProps<{courseId:string;page:number;language:string;languages:Record<string,string>;availableLanguages:string[];records:any[];completed:boolean}>()
const emit=defineEmits<{refresh:[];created:[id:string]}>()
const instruction=ref(''),selectedLanguage=ref(props.language),allPages=ref(false),withImages=ref(true),automatic=ref(false),remember=ref(false),execute=ref(true),busy=ref(false),error=ref(''),current=ref<any>(),selected=ref<string[]>([])
const kinds:Record<string,string>={script:'讲稿',slide_text:'课件文字',subtitle:'字幕',speech:'语音',avatar:'数字人',layout:'版式'}
const stageNames:Record<number,string>={2:'更新译文、语音与视频',3:'更新语音及后续结果',4:'更新数字人与视频',5:'仅重新合成视频'}
const states:Record<string,string>={proposed:'待采纳',needs_input:'待补充信息',applying:'处理中',applied:'已创建修订版'}
const active=computed(()=>current.value||props.records?.[props.records.length-1])
watch(()=>props.courseId,()=>{current.value=undefined;selected.value=[];error.value='';instruction.value='';selectedLanguage.value=props.language})
watch(active,row=>{selected.value=row?.changes?.map((x:any)=>x.id)||[]},{immediate:true})
async function post(action:string,payload:any){return api<any>('/v1/studio/courses/'+encodeURIComponent(props.courseId)+'/'+action,{method:'POST',body:JSON.stringify(payload),signal:AbortSignal.timeout(600000)})}
async function generate(){busy.value=true;error.value='';try{current.value=await post('suggest-revision',{instruction:instruction.value,language:selectedLanguage.value,...(allPages.value?{}:{page:props.page}),withImages:withImages.value,autoApply:automatic.value,remember:remember.value,execute:execute.value});if(current.value.releaseTaskId)emit('created',current.value.releaseTaskId);emit('refresh')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function apply(){if(!active.value)return;busy.value=true;error.value='';try{current.value=await post('apply-suggestion',{suggestionId:active.value.id,selectedIds:selected.value,remember:remember.value,execute:execute.value});emit('created',current.value.releaseTaskId);emit('refresh')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template>
 <section class="ai-revision" :aria-busy="busy">
  <h3>AI 修改建议</h3><p>直接描述希望如何修改。模型结合课程文字、可用画面、反馈与已采纳记忆，提出具体修改内容和理由。</p>
  <label>修改要求<textarea v-model="instruction" rows="4" maxlength="1200" placeholder="例如：第 2 页对初学者太抽象，使用已有概念增加一个生活例子；英语表达自然一些，术语保持一致。"/></label>
  <div class="quick"><button type="button" @click="instruction='保持事实、数字和术语不变，将讲稿改成更适合零基础学生的直接讲授表达。'">更适合初学者</button><button type="button" @click="instruction='检查并统一已确认的术语译法，只提出具体且有来源的修改。'">统一术语</button><button type="button" @click="instruction='检查讲稿是否遗漏页面图文中的重要内容，提出具体补充；缺少信息时先询问。'">检查图文与讲稿</button></div>
  <div class="options"><label>修订语种<select v-model="selectedLanguage"><option value="source">原语言</option><option v-for="code in availableLanguages" :key="code" :value="code">{{languages[code]||code}}</option></select></label><label><input v-model="allPages" type="checkbox">整门课程（否则仅第 {{page}} 页）</label><label><input v-model="withImages" type="checkbox">结合可用课件画面</label></div>
  <div class="options"><label><input v-model="automatic" type="checkbox">生成建议后直接采纳全部有效修改</label><label><input v-model="execute" type="checkbox">采纳后开始生成修订版</label><label><input v-model="remember" type="checkbox">将采纳的修改要求保存为课程记忆</label></div>
  <p v-if="!completed" class="hint">课程完成后可生成修订方案；当前讲稿和要求可以先使用输入框旁的 AI 填写建议。</p>
  <button type="button" class="primary" :disabled="busy||!completed||!instruction.trim()" @click="generate">{{busy?'正在处理…':'生成修改建议'}}</button>
  <p v-if="error" class="error" role="alert">{{error}}</p>
  <div v-if="active" class="proposal"><h4>{{states[active.status]||active.status}}</h4><p>{{active.summary}}</p><p>原要求：{{active.instruction}}</p><p>读取画面页码：{{active.imagePages?.join('、')||'未读取图片'}}</p><ul><li v-for="question in active.questions" :key="question">{{question}}</li></ul><article v-for="change in active.changes" :key="change.id"><label class="change-title"><input v-model="selected" type="checkbox" :value="change.id" :disabled="active.status==='applied'">第 {{change.page}} 页 · {{kinds[change.kind]}} · {{stageNames[change.startStage]}}</label><p>{{change.reason}}</p><div v-if="change.oldText||change.text" class="comparison"><div><b>现有内容</b><pre>{{change.oldText||'原有媒体或版式'}}</pre></div><div><b>建议内容</b><pre>{{change.text||'按当前要求重新生成对应媒体或版式'}}</pre></div></div></article><div v-if="active.status==='proposed'" class="quick"><button type="button" class="primary" :disabled="busy||!selected.length" @click="apply">采纳选中建议，创建修订版</button><button type="button" @click="selected=active.changes.map((x:any)=>x.id)">全选</button><button type="button" @click="selected=[]">清空选择</button></div><p v-if="active.executionMessage" class="hint">{{active.executionMessage}} 修订草稿已保存。</p><a v-if="active.releaseTaskId" :href="'#/studio?id='+active.releaseTaskId">打开修订版工作区</a></div>
  <details v-if="records?.length"><summary>我的修改建议记录（{{records.length}}）</summary><button v-for="row in [...records].reverse()" :key="row.id" type="button" class="history" @click="current=row">{{new Date(row.createdAt).toLocaleString()}} · {{states[row.status]||row.status}} · {{row.instruction}}</button></details>
 </section>
</template>
<style scoped>.ai-revision{color:#244c36}.ai-revision p{font-size:13px;line-height:1.8;white-space:pre-wrap}.ai-revision textarea{box-sizing:border-box;display:block;width:100%;padding:12px;font:inherit;font-size:15px;border:1px solid #c6d9cd;border-radius:8px;margin-top:7px}.ai-revision label{font-size:13px}.options,.quick{display:flex;gap:10px 16px;align-items:center;flex-wrap:wrap;margin:14px 0}.options label{display:flex;gap:7px;align-items:center}.ai-revision select{padding:8px;border:1px solid #c4d7cb;border-radius:6px;background:white}.ai-revision button,.ai-revision a{font:inherit;font-size:13px;border:1px solid #c6d9cd;border-radius:7px;padding:9px 13px;background:#f2f7f3;color:#2b6245;cursor:pointer}.ai-revision button:disabled{opacity:.5;cursor:default}.ai-revision .primary{background:#286447;color:white}.ai-revision article{border:1px solid #dbe7df;border-radius:9px;margin:14px 0;padding:14px}.change-title{display:flex;gap:8px;align-items:center;font-weight:600}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:12px}.comparison>div{background:#f6f9f7;padding:12px;border-radius:7px;min-width:0}.comparison pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;font-size:14px;max-height:300px;overflow:auto}.ai-revision .error{color:#a24233}.ai-revision .hint{background:#f6f4e9;padding:10px;border-radius:6px}.ai-revision details{margin-top:22px}.ai-revision .history{display:block;width:100%;text-align:left;margin:6px 0;overflow-wrap:anywhere}@media(max-width:700px){.comparison{grid-template-columns:1fr}}</style>
